sys_ui_action.script:
function temp_save() {
    var fields = g_form.getEditableFields();

    for (var i = 0; i < fields.length; i++) {
        if (g_form.isMandatory(fields[i])) {
            g_form.setMandatory(fields[i], false);
        }
    }

    gsftSubmit(null, g_form.getFormElement(), 'fukusuu.sakusei');
}

if (typeof window == 'undefined') {
    var kaisuu = current.sakusei_kaisuu - 1;

    current.fukusuu_flg = false;
    current.sakusei_kaisuu = null;
    current.update();

    for (var i = 0; i < kaisuu; i++) {

        var gr = new GlideRecord('x_1882833_organi_0_meisai');
		gr.initialize();

        if (!gs.nil(current.bikou)) {
            gr.bikou = current.bikou;
        }
        if (!gs.nil(current.bikou_gen)) {
            gr.bikou_gen = current.bikou_gen;
        }
        if (!gs.nil(current.grade_sin)) {
            gr.grade_sin = current.grade_sin;
        }
        if (!gs.nil(current.hatureibi)) {
            gr.hatureibi = current.hatureibi;
        }
        if (!gs.nil(current.jissibi)) {
            gr.jissibi = current.jissibi;
        }
        if (!gs.nil(current.juukyo)) {
            gr.juukyo = current.juukyo;
        }
        if (!gs.nil(current.kazoku)) {
            gr.kazoku = current.kazoku;
        }
        if (!gs.nil(current.kenmu1_sin)) {
            gr.kenmu1_sin = current.kenmu1_sin;
        }
        if (!gs.nil(current.kenmu2_sin)) {
            gr.kenmu2_sin = current.kenmu2_sin;
        }
        if (!gs.nil(current.kenmu3_sin)) {
            gr.kenmu3_sin = current.kenmu3_sin;
        }
        if (!gs.nil(current.kenmu4_sin)) {
            gr.kenmu4_sin = current.kenmu4_sin;
        }
        if (!gs.nil(current.kenmu5_sin)) {
            gr.kenmu5_sin = current.kenmu5_sin;
        }
        if (!gs.nil(current.kimuti_sin)) {
            gr.kimuti_sin = current.kimuti_sin;
        }
        if (!gs.nil(current.naiji_umu)) {
            gr.naiji_umu = current.naiji_umu;
        }
        if (!gs.nil(current.naiji_yotei)) {
            gr.naiji_yotei = current.naiji_yotei;
        }
        // if (!gs.nil(current.name)) {
        //     gr.name = current.name;
        // }
        if (!gs.nil(current.ninmen)) {
            gr.ninmen = current.ninmen;
        }
        if (!gs.nil(current.reason)) {
            gr.reason = current.reason;
        }
        if (!gs.nil(current.role_sin)) {
            gr.role_sin = current.role_sin;
        }
        if (!gs.nil(current.ryou)) {
            gr.ryou = current.ryou;
        }
        if (!gs.nil(current.shumu_sin)) {
            gr.shumu_sin = current.shumu_sin;
        }
        if (!gs.nil(current.sinsei_number)) {
            gr.sinsei_number = current.sinsei_number;
        }
        if (!gs.nil(current.tyokkann_sin)) {
            gr.tyokkann_sin = current.tyokkann_sin;
        }
        if (!gs.nil(current.type)) {
            gr.type = current.type;
        }
        if (!gs.nil(current.vu_sin)) {
            gr.vu_sin = current.vu_sin;
        }
        if (!gs.nil(current.yakui_sin)) {
            gr.yakui_sin = current.yakui_sin;
        }

        gr.insert();

    }

    var url = '/now/nav/ui/classic/params/target/x_1882833_organi_0_jinji_idou.do%3Fsys_id%3D' + current.sinsei_number;
    gs.setRedirect(url);
}
